sys_ui_action.script:
var city = (current.getValue('location') || '').trim();

if (!city) {
    gs.addErrorMessage('Please enter a city name.');
    action.setRedirectURL(current);

} else {
    // Validate the city and retrieve weather first.
    // No record ID is passed, so WeatherService does not
    // insert or update a record until validation succeeds.
    var result = new WeatherService().getWeather(city);

    if (!result.success) {
        gs.addErrorMessage(result.message);

        // Do not save a new record when the lookup fails.
        if (!current.isNewRecord()) {
            action.setRedirectURL(current);
        }

    } else {
        // The API succeeded. Save the new record with weather data.
        current.setValue('location', result.location);
        current.setValue('latitude', result.latitude);
        current.setValue('region', result.region);
        current.setValue('longitude', result.longitude);
        current.setValue(
            'temperature_in_celsius',
            result.temperature
        );

        var savedId;

        if (current.isNewRecord()) {
            savedId = current.insert();
        } else {
            savedId = current.update();
        }

        if (savedId) {
            gs.addInfoMessage(
                'Weather retrieved and saved successfully.'
            );
            action.setRedirectURL(current);
        } else {
            gs.addErrorMessage('Unable to save the weather record.');
        }
    }
}
